for x in range(1,n-y+1):
    if (x+y)//k >=100000:
        break

    if (x+y)%k == 0:
        xl.append(x)
        xf = x
        break

while xf!=-1:
    xf += k
    if xf > n:
        break
    xl.append(xf)

if len(xl)==0:
    print(-1)
else:
    ans = ""
    for k in xl:
        ans+= str(k)+" "
    print(ans)

